class Solution {public:string minimizeStringValue(string s){
 vector<int> f(26);int q=0;for(char c:s)if(c=='?')++q;else ++f[c-'a'];
 string chosen;for(int i=0;i<q;i++){int b=min_element(f.begin(),f.end())-f.begin();++f[b];chosen.push_back(char('a'+b));}
 sort(chosen.begin(),chosen.end());int j=0;for(char &c:s)if(c=='?')c=chosen[j++];return s;
}};
